window.TALKS = [
{t:"Hierarchy of Controls",pts:["Eliminate the hazard first; PPE is the last resort","Substitute: lower-risk chemical, prefab, lighter bags","Engineering: guards, LEV, edge rails, RCDs","Administrative: permits, procedures, rotation","PPE: only when the above are exhausted; wear it correctly"]},
{t:"Falls from Height",pts:["Falls are the top killer in construction worldwide","Use guardrails and covers before harnesses","Tie off 100% to a rated anchor, never to scaffold tubes","Inspect harness before each use; report any fall","Ladders are for access, not prolonged work"]},
{t:"Struck by Plant & Vehicles",pts:["Stay out of swing/travel zones; eye contact with operator","Banksman for all reversing in congested areas","Walk on marked pedestrian routes","Hi-vis always; class 3 at night","Never ride on loads or in buckets"]},
{t:"Electrical Safety on Site",pts:["Every circuit through a 30 mA RCD; test weekly","Damaged cable = tag out and report","Keep plant and ladders away from overhead lines","Never touch a victim in contact with live electricity — isolate first","Only licensed electricians connect to DBs"]},
{t:"Excavation Collapse",pts:["One cubic metre of soil weighs about 1.5–2 tonnes","No entry > 1.5 m without shoring/sloping/box","Spoil and plant at least 1 m from the edge","Ladder every 7.5 m; inspect daily and after rain","Treat every underground cable as live"]},
{t:"Hot Work & Fire",pts:["Permit first; clear combustibles 11 m","Fire watch with extinguisher during and 30–60 min after","Gas test for 0% LEL near process/tanks","Flashback arrestors on both ends; acetylene ≤ 1 bar","Know the nearest extinguisher, exit and assembly point"]},
{t:"Confined Space",pts:["Never enter without permit, gas test and attendant","O2 19.5–23.5%, LEL < 10%, H2S < 10 ppm, CO < 25 ppm","Isolate by blinding, not by closing valves","Rescuers die too — never enter to rescue without SCBA and retrieval","Evacuate on alarm or dizziness"]},
{t:"Lockout / Tagout",pts:["Isolate every energy source, not just the stop button","One person, one lock, one key","Test for dead with a proved tester","Release stored energy: pressure, springs, raised parts","Only you remove your lock"]},
{t:"Heat Stress",pts:["Drink 250 ml every 15–20 min, before you feel thirsty","Rest in shade; heavy work early/late","New workers need 5–7 days to acclimatise","Confusion/no sweating = heat stroke: cool first, call 108","Look out for your buddy"]},
{t:"Manual Handling",pts:["Use plant or trolleys; split loads","Max 25 kg single-person; team lift above","Plan the route; bend knees; keep load close; no twisting","Report pain early","Cement bags: wear gloves; wash skin"]},
{t:"Scaffolds",pts:["Green tag only; red tag means do not use","Full boards, guardrails, toe boards, ties","Never remove a tie or brace","Use the ladder access, not the frames","Report any damage or missing part"]},
{t:"Lifting Operations",pts:["Lift plan and signaller for every lift","Never stand under a load","Tag lines to control swing","Watch overhead lines: 3 m LT / 6 m HT clearance","Stop if the LMI alarms or wind rises"]},
{t:"Chemical Safety & SDS",pts:["Read the label and SDS sections 2, 7, 8 before use","Right gloves and goggles for the chemical","Never mix; store incompatibles apart","Spill: isolate, PPE, contain, report","Wash before eating; no food in work areas"]},
{t:"Dust & Silica",pts:["Dry cutting concrete/stone releases silica — use water or LEV","FFP3/P100 respirator for silica; fit-tested, clean-shaven","Silicosis is incurable; it appears years later","No dry sweeping; vacuum or wet","Change out of dusty clothes before going home"]},
{t:"Noise",pts:["If you must shout at 1 m, protection is needed","Hearing loss is permanent and painless","Plugs/muffs in marked zones; fit them properly","Maintain silencers and enclosures","Attend your annual hearing test"]},
{t:"PPE Basics",pts:["Helmet with chin strap at height; boots; hi-vis — always","Inspect PPE daily; replace damaged free of charge","Right PPE for the task: goggles vs face shield vs welding helmet","Respirator fit: no beards for tight-fit masks","PPE never replaces a guard or a permit"]},
{t:"Housekeeping",pts:["Clean as you go; trips are the most common injury","Nails out of timber; tie wire in bins","Keep walkways and exits clear","Segregate waste; no burning","Store materials stable, not above 1.5 m by hand"]},
{t:"Emergency Response",pts:["Know the alarm sound and your assembly point","Raise alarm first, fight fire only if trained and safe","Call 112 / 101 / 108; give location and nature","Never use lifts in fire","Head-count: tell your supervisor you are out"]},
{t:"Near Miss Reporting",pts:["Every near miss is a free lesson","No blame for reporting","Report within the shift to supervisor","Fix the cause, not the person","Celebrate the reports, trend them monthly"]},
{t:"Monsoon Safety",pts:["Inspect excavations and scaffolds after every rain","Lightning: stop WAH and crane work","Keep electrical DBs covered and cables raised","Slips: clean mud, use grip boots","Dengue/malaria: no stagnant water on site"]},
{t:"Women's Safety & Respect at Work",pts:["Zero tolerance for harassment; ICC contact displayed","Night work: transport and security are your right","Report concerns confidentially","Separate facilities must be clean and lockable","Everyone shares responsibility for a respectful site"]},
{t:"Working Near Overhead Lines",pts:["Assume every line is live","Keep tippers, booms, scaffold tubes and ladders well clear","Use goal posts and a spotter","If contact occurs: stay in the cab, jump clear only if on fire — keep others away","Ask for a shutdown or shrouding"]}
];

